
import sys
import marshal
import types
import struct
import hashlib
import io
import os

# Cross-platform safe stdout/stderr setup
# Avoid codecs writer that can fail in some environments (IDLE, IDEs, etc.)
try:
    if hasattr(sys.stdout, 'buffer') and hasattr(sys.stderr, 'buffer'):
        # Redirect to text mode for consistent output
        sys.stdout = open(sys.stdout.buffer.fileno(), 'w', encoding='utf-8', closefd=False)
        sys.stderr = open(sys.stderr.buffer.fileno(), 'w', encoding='utf-8', closefd=False)
except Exception:
    # Fallback: just ensure we're using text mode
    import io
    sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8') if hasattr(sys.stdout, 'buffer') else sys.stdout
    sys.stderr = io.TextIOWrapper(sys.stderr.buffer, encoding='utf-8') if hasattr(sys.stderr, 'buffer') else sys.stderr

COMP_NAMES = {0: "none", 1: "zlib", 2: "gzip", 3: "bz2", 4: "lzma"}

# Maximum safe payload size (100MB) to prevent memory exhaustion
MAX_PAYLOAD_SIZE = 100 * 1024 * 1024

_CONTAINER = bytes.fromhex("")

def _safe_marshal_loads(data):
    """Safely unmarshal data with size and corruption checks."""
    # Check for obviously corrupted data (too small)
    if len(data) < 4:
        raise ValueError("Data too small to be valid marshal")
    return marshal.loads(data)

def _decompress(payload, comp_id):
    if comp_id == 0:
        return payload

    # Check payload size before decompression
    if len(payload) > MAX_PAYLOAD_SIZE:
        raise ValueError(f"Compressed payload too large: {len(payload)} bytes")

    try:
        if comp_id == 1:
            import zlib
            return zlib.decompress(payload)
        elif comp_id == 2:
            import gzip
            buf = io.BytesIO(payload)
            with gzip.GzipFile(fileobj=buf, mode='rb') as f:
                return f.read()
        elif comp_id == 3:
            import bz2
            return bz2.decompress(payload)
        elif comp_id == 4:
            import lzma
            return lzma.decompress(payload)
    except (zlib.error, OSError, EOFError) as e:
        raise ValueError(f"Decompression failed: {e}")

    return payload

def _parse_container(data):
    MAGIC = b"MRSH"
    HEADER_SIZE = 24
    CHECKSUM_SIZE = 32

    if len(data) < HEADER_SIZE:
        raise ValueError("Container too small")

    header = struct.unpack(">4s H H B B I B B Q", data[:HEADER_SIZE])
    magic, version, _, py_major, py_minor = header[0], header[1], header[2], header[3], header[4]

    if magic != MAGIC:
        raise ValueError("Invalid container magic")
    if version != 1:
        raise ValueError("Incompatible container version")

    layer_count, comp_id, obf_id, payload_len = header[5:9]

    # Validate payload length to prevent buffer issues
    if payload_len <= 0 or payload_len > MAX_PAYLOAD_SIZE:
        raise ValueError(f"Invalid payload length: {payload_len}")

    expected_size = HEADER_SIZE + CHECKSUM_SIZE + payload_len
    if len(data) < expected_size:
        raise ValueError(f"Container truncated: expected {expected_size} bytes, got {len(data)}")

    checksum = data[HEADER_SIZE:HEADER_SIZE + CHECKSUM_SIZE]
    payload = data[HEADER_SIZE + CHECKSUM_SIZE:HEADER_SIZE + CHECKSUM_SIZE + payload_len]

    # Verify checksum
    if hashlib.sha256(payload).digest() != checksum:
        raise ValueError("Checksum mismatch - data may be corrupted")

    return {
        "python_major": py_major,
        "python_minor": py_minor,
        "layer_count": layer_count,
        "compression_id": comp_id,
        "obfuscation_id": obf_id,
        "payload": payload,
    }

def _deobfuscate(payload, obf_id):
    if obf_id == 0:
        return payload

    try:
        import base64
        payload = base64.b64decode(payload)
    except Exception as e:
        raise ValueError(f"Base64 decode failed: {e}")

    key = b"MARSH_KEY_2024"
    key_len = len(key)
    result = bytearray(len(payload))
    for i, byte in enumerate(payload):
        result[i] = byte ^ key[i % key_len]
    return bytes(result)

def _unmarshal_layers(data, count):
    """Unmarshal layers iteratively with safety checks."""
    for i in range(count):
        # Verify data is not growing unreasonably (could indicate corruption)
        input_size = len(data)
        data = _safe_marshal_loads(data)
        output_size = len(data) if isinstance(data, bytes) else 0

        # If output is significantly larger than input, check for corruption
        if output_size > input_size * 100 and input_size > 100:
            raise ValueError(f"Layer {i+1}: unusual size increase detected ({input_size} -> {output_size})")
    return data

def _run():
    try:
        container = _parse_container(_CONTAINER)

        built_major = container.get("python_major", 3)
        built_minor = container.get("python_minor", 12)
        current_major = sys.version_info.major
        current_minor = sys.version_info.minor

        # Python 3.12+ compatibility: allow minor version flexibility
        # Only enforce major version match
        if built_major != current_major:
            raise RuntimeError(
                "Incompatible Python version. "
                "Built for " + str(built_major) + "." + str(built_minor) + ", "
                "running " + str(current_major) + "." + str(current_minor)
            )

        # For minor version differences, try to run anyway (Python 3.12+ has good compatibility)
        if built_minor != current_minor:
            if built_minor < 12 and current_minor >= 12:
                msg = ("Note: Protected code was built for Python "
                       + str(built_major) + "." + str(built_minor)
                       + " but running on " + str(current_major) + "." + str(current_minor)
                       + ". Attempting to run anyway...")
                sys.stderr.write(msg + chr(10))
            elif built_minor >= 12 and current_minor >= 12:
                msg = ("Running on Python " + str(current_major) + "." + str(current_minor)
                       + " (built for " + str(built_major) + "." + str(built_minor) + ")")
                sys.stderr.write(msg + chr(10))

        payload = container["payload"]

        # Decompress if needed
        if container["compression_id"] != 0:
            payload = _decompress(payload, container["compression_id"])

        # Deobfuscate if needed
        if container.get("obfuscation_id", 0) != 0:
            payload = _deobfuscate(payload, container["obfuscation_id"])

        # Unmarshal the code object
        code = _unmarshal_layers(payload, container["layer_count"])

        if not hasattr(code, 'co_code'):
            raise ValueError("Unmarshaled data is not a valid Python code object")

        module = types.ModuleType("__main__")
        module.__file__ = getattr(sys.modules['__main__'], '__file__', '<protected>')

        exec(code, module.__dict__)

        return module

    except SystemExit:
        raise
    except Exception as e:
        import traceback
        sys.stderr.write("Protected code error: " + str(e) + chr(10))
        traceback.print_exc()
        raise

if __name__ == "__main__":
    try:
        _run()
    except SystemExit as e:
        sys.exit(e.code)
    except (KeyboardInterrupt, EOFError):
        pass
    except Exception:
        sys.exit(1)
